<script lang="ts">
 import {onMount} from 'svelte';
 import {LayoutDashboard,ShoppingCart,Package,Boxes,Truck,Users,ChartNoAxesCombined,Settings,Search,Plus,Minus,Trash2,Menu,Printer,RotateCcw,Check,AlertTriangle,LogOut,Tag,HeartPulse,Barcode,CalendarClock,ArrowDownToLine,ShieldCheck,Download,Upload,ChevronDown,Activity,Wallet,PackageCheck,Clock3,Building2,Filter,Eye,Archive,RefreshCw,X,FileText} from 'lucide-svelte';
 import {db,rupiah,uuid,type Product,type Category,type Brand,type Supplier,type Customer,type Sale,type Purchase,type Batch,type SerialUnit,type Tracking} from './lib/database/schema';
 import {seed} from './lib/database/seed';
 import {available,saveProduct,receivePurchase,checkout as commitSale} from './lib/services/operations';
 type Page='Overview'|'Kasir / POS'|'Produk'|'Stok Barang'|'Batch & Expiry'|'Serial Number'|'Pembelian'|'Riwayat Penjualan'|'Kategori'|'Merek'|'Supplier'|'Pelanggan'|'Laporan'|'Pengaturan';
 let page:Page='Overview', products:Product[]=[], categories:Category[]=[], brands:Brand[]=[], suppliers:Supplier[]=[], customers:Customer[]=[], sales:Sale[]=[], purchases:Purchase[]=[], batches:Batch[]=[], serials:SerialUnit[]=[], stock:Record<string,number>={};let ready=false,loggedIn=false,role='owner',sidebar=true,menuMobile=false,query='',notice='',categoryFilter='all',showProduct=false,showPurchase=false,showCustomer=false,showSupplier=false,showMaster=false,showPayment=false,showReceipt:Sale|null=null,editing:Product|null=null,masterKind='Kategori',cart:{product:Product;qty:number;serialIds:string[]}[]=[],selectedCustomer='',payment='Tunai',paid=0,discount=0,searchBarcode='';let purchaseProduct='',purchaseSupplier='',purchaseQty=1,purchaseCost=0,purchaseBatch='',purchaseLot='',purchaseExpiry='',purchaseSerials='';let customerName='',customerType='Individu',customerPhone='',supplierName='',supplierPhone='',masterName='';let form:any={};let expiryFilter=30;
 let shownNav:any[]=[],filtered:Product[]=[],subtotal=0,total=0,itemCount=0,todaySales:Sale[]=[],revenue=0,todayCount=0,lowStock:Product[]=[],inventoryValue=0,expiring:Batch[]=[],expired:Batch[]=[];
 const nav:{title:string;icon:any;items:Page[]}[]=[{title:'MENU UTAMA',icon:LayoutDashboard,items:['Overview']},{title:'TRANSAKSI',icon:ShoppingCart,items:['Kasir / POS','Riwayat Penjualan']},{title:'MASTER DATA',icon:Package,items:['Produk','Kategori','Merek','Supplier','Pelanggan']},{title:'INVENTORY',icon:Boxes,items:['Stok Barang','Batch & Expiry','Serial Number','Pembelian']},{title:'ANALISIS',icon:ChartNoAxesCombined,items:['Laporan','Pengaturan']}];
 const cashierPages:Page[]=['Overview','Kasir / POS','Riwayat Penjualan','Pelanggan'];
 $: shownNav=role==='cashier'?nav.map(g=>({...g,items:g.items.filter(p=>cashierPages.includes(p))})).filter(g=>g.items.length):nav;
 $: filtered=products.filter(p=>p.active&&(categoryFilter==='all'||p.categoryId===categoryFilter)&&`${p.name} ${p.sku} ${p.barcode} ${brands.find(b=>b.id===p.brandId)?.name||''}`.toLowerCase().includes(query.toLowerCase()));
 $: subtotal=cart.reduce((a,x)=>a+x.qty*x.product.price,0),total=Math.max(0,subtotal-discount),itemCount=cart.reduce((a,x)=>a+x.qty,0);
 $: todaySales=sales.filter(s=>s.status==='COMPLETED'&&new Date(s.date).toDateString()===new Date().toDateString()),revenue=todaySales.reduce((a,s)=>a+s.total,0),todayCount=todaySales.length;
 $: lowStock=products.filter(p=>p.active&&(stock[p.id]||0)<=p.minimum&&stock[p.id]!==undefined),inventoryValue=products.reduce((a,p)=>a+(stock[p.id]||0)*p.cost,0),expiring=batches.filter(b=>b.status==='ACTIVE'&&b.remaining>0&&b.expiry>=new Date().toISOString().slice(0,10)&&new Date(b.expiry).getTime()-Date.now()<=expiryFilter*86400000),expired=batches.filter(b=>b.status==='ACTIVE'&&b.remaining>0&&b.expiry<new Date().toISOString().slice(0,10));
 async function refresh(){[products,categories,brands,suppliers,customers,sales,purchases,batches,serials]=await Promise.all([db.products.toArray(),db.categories.toArray(),db.brands.toArray(),db.suppliers.toArray(),db.customers.toArray(),db.sales.toArray(),db.purchases.toArray(),db.batches.toArray(),db.serials.toArray()]);stock={};for(const p of products)stock[p.id]=await available(p);sales.sort((a,b)=>b.date.localeCompare(a.date));purchases.sort((a,b)=>b.date.localeCompare(a.date));}
 onMount(async()=>{try{await seed();await refresh();role=localStorage.getItem('medikapos-user')||'';loggedIn=!!role;ready=true;}catch(e){notify('Database lokal tidak dapat dibuka. '+String(e));ready=true;}});
 function notify(s:string){notice=s;setTimeout(()=>notice='',3200)}
 function login(r:string){role=r;loggedIn=true;localStorage.setItem('medikapos-user',r)}function logout(){loggedIn=false;localStorage.removeItem('medikapos-user');page='Overview'}
 function openNew(){editing=null;form={sku:'',barcode:'',name:'',brandId:brands[0]?.id||'',categoryId:categories[0]?.id||'',unit:'PCS',tracking:'QUANTITY',cost:0,price:0,minimum:5,manufacturer:'',description:''};showProduct=true}
 function openEdit(p:Product){editing=p;form={...p};showProduct=true}
 async function persistProduct(){try{if(!form.sku?.trim()||!form.name?.trim())return notify('SKU dan nama produk wajib diisi.');const old=editing;const row:Product={...form,id:old?.id||uuid(),sku:form.sku.trim(),barcode:(form.barcode||'').trim(),name:form.name.trim(),cost:Math.round(Number(form.cost)||0),price:Math.round(Number(form.price)||0),minimum:Number(form.minimum)||0,active:old?.active??true,createdAt:old?.createdAt||new Date().toISOString()};await saveProduct(row,old||undefined);showProduct=false;await refresh();notify(old?'Produk diperbarui':'Produk ditambahkan');}catch(e){notify((e as Error).message)}}
 async function removeProduct(p:Product){if(!confirm(`Hapus ${p.name}? Histori stok/transaksi dipertahankan.`))return;const used=await db.movements.where('productId').equals(p.id).count();if(used)await db.products.update(p.id,{active:false});else await db.products.delete(p.id);await refresh();notify(used?'Produk dinonaktifkan karena memiliki histori':'Produk dihapus')}
 async function addToCart(p:Product){const q=stock[p.id]||0;if(q<1)return notify('Stok jual produk habis.');const found=cart.find(x=>x.product.id===p.id);if(found){if(found.qty>=q)return notify('Jumlah melampaui stok.');found.qty++;cart=[...cart];}else cart=[...cart,{product:p,qty:1,serialIds:[]}];}
 function changeQty(p:Product,d:number){const x=cart.find(i=>i.product.id===p.id);if(!x)return;if(x.qty+d>(stock[p.id]||0))return notify('Jumlah melampaui stok.');if(x.qty+d<1)cart=cart.filter(i=>i.product.id!==p.id);else{x.qty+=d;if(d<0)x.serialIds=x.serialIds.slice(0,x.qty);cart=[...cart]}}
 function chooseSerial(item:{product:Product;qty:number;serialIds:string[]},id:string,index:number){item.serialIds[index]=id;cart=[...cart]}
 async function payNow(){if(!cart.length)return;paid=Math.max(paid,total);showPayment=true}
 async function finishSale(){try{const sale=await commitSale(cart.map(x=>({product:x.product,qty:x.qty,serialIds:x.serialIds})),selectedCustomer||'Pelanggan Umum',payment,Math.round(discount),Math.round(paid),role);cart=[];showPayment=false;discount=0;paid=0;await refresh();showReceipt=sale;notify('Penjualan tersimpan di IndexedDB.')}catch(e){notify((e as Error).message);await refresh()}}
 async function purchase(){const p=products.find(x=>x.id===purchaseProduct);if(!p)return notify('Pilih produk.');try{await receivePurchase({supplierId:purchaseSupplier,product:p,qty:Number(purchaseQty),cost:Math.round(Number(purchaseCost)||p.cost),batch:purchaseBatch,lot:purchaseLot,expiry:purchaseExpiry,serials:purchaseSerials.split(/[\n,]+/).map(s=>s.trim()).filter(Boolean)});showPurchase=false;await refresh();notify('Pembelian tersimpan dan stok bertambah.');}catch(e){notify((e as Error).message)}}
 async function saveCustomer(){if(!customerName.trim())return notify('Nama pelanggan wajib diisi.');await db.customers.add({id:uuid(),name:customerName.trim(),type:customerType,phone:customerPhone,institution:customerType==='Individu'?'':customerName});showCustomer=false;customerName='';customerPhone='';await refresh();notify('Pelanggan ditambahkan')}
 async function saveSupplier(){if(!supplierName.trim())return notify('Nama supplier wajib diisi.');await db.suppliers.add({id:uuid(),name:supplierName,company:supplierName,phone:supplierPhone,address:'',active:true});showSupplier=false;supplierName='';supplierPhone='';await refresh();notify('Supplier ditambahkan')}
 async function saveMaster(){if(!masterName.trim())return notify('Nama wajib diisi.');if(masterKind==='Kategori'){await db.categories.add({id:uuid(),name:masterName,active:true});categories=await db.categories.toArray()}else{await db.brands.add({id:uuid(),name:masterName,active:true});brands=await db.brands.toArray()}masterName='';showMaster=false;notify(`${masterKind} ditambahkan`)}
 async function adjust(p:Product){const value=prompt(`Stok baru untuk ${p.name} (bilangan bulat):`,String(stock[p.id]||0));if(value===null)return;const qty=Number(value),before=stock[p.id]||0;if(!Number.isInteger(qty)||qty<0)return notify('Stok harus bilangan bulat nol atau lebih.');if(p.tracking!=='QUANTITY')return notify('Untuk produk batch/serial, gunakan pembelian atau ubah status unit agar histori tetap konsisten.');const bal=await db.balances.where('productId').equals(p.id).first();await db.transaction('rw',db.balances,db.movements,async()=>{if(bal)await db.balances.update(bal.id,{quantity:qty});else await db.balances.add({id:uuid(),productId:p.id,quantity:qty,location:'Gudang · G1'});await db.movements.add({id:uuid(),productId:p.id,type:qty>=before?'ADJUSTMENT_IN':'ADJUSTMENT_OUT',quantity:Math.abs(qty-before),before,after:qty,reference:`ADJ-${Date.now()}`,reason:'Penyesuaian stok manual',date:new Date().toISOString()})});await refresh();notify('Penyesuaian stok dicatat')}
 async function print(){window.print()}
 function csvDownload(rows:any[][],name:string){const csv=rows.map(row=>row.map(x=>`"${String(x??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
 async function exportBackup(){const tables=['categories','brands','products','suppliers','customers','balances','batches','serials','sales','purchases','movements','settings'] as const;const payload:any={format:'medikapos-backup',version:1,exportedAt:new Date().toISOString()};for(const t of tables)payload[t]=await (db[t] as any).toArray();const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}));a.download='medikapos-backup.json';a.click();URL.revokeObjectURL(a.href);notify('Backup JSON diunduh')}
 async function importBackup(file:File){try{const data=JSON.parse(await file.text());if(data.format!=='medikapos-backup'||data.version!==1)throw Error('Format backup tidak dikenali.');if(!confirm('Data tabel yang ada akan diganti. Lanjutkan restore?'))return;const tables=['categories','brands','products','suppliers','customers','balances','batches','serials','sales','purchases','movements','settings'] as const;await db.transaction('rw',tables.map(t=>db[t]) as any,async()=>{for(const t of tables){if(!Array.isArray(data[t]))throw Error(`Tabel ${t} tidak valid.`);}for(const t of tables){await (db[t] as any).clear();await (db[t] as any).bulkAdd(data[t]);}});await refresh();notify('Restore selesai.')}catch(e){notify(`Restore gagal: ${(e as Error).message}`)}}
 async function resetDemo(){if(!confirm('Seluruh data browser saat ini akan diganti dengan data demo awal. Unduh backup terlebih dahulu bila perlu.'))return;await db.delete();await db.open();await seed();await refresh();notify('Data demo dipulihkan')}
 function printReceipt(){window.print()}
 function title(page:Page){return page==='Overview'?'Overview':page}
 function date(s:string){return new Date(s).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'})}
 function productCategory(p:Product){return categories.find(c=>c.id===p.categoryId)?.name||'—'}function productBrand(p:Product){return brands.find(b=>b.id===p.brandId)?.name||'—'}
 function lastSevenDays(rows:Sale[]){return Array.from({length:7},(_,i)=>{const d=new Date();d.setHours(0,0,0,0);d.setDate(d.getDate()-6+i);const key=d.toDateString();return{label:d.toLocaleDateString('id-ID',{weekday:'short'}),total:rows.filter(s=>s.status==='COMPLETED'&&new Date(s.date).toDateString()===key).reduce((a,s)=>a+s.total,0)}})}
 function bestSellers(rows:Sale[],ps:Product[]){const totals:Record<string,{qty:number;revenue:number}>={};for(const s of rows.filter(x=>x.status==='COMPLETED'))for(const item of s.items){totals[item.productId]??={qty:0,revenue:0};totals[item.productId].qty+=item.qty;totals[item.productId].revenue+=item.qty*item.price}return Object.entries(totals).map(([id,x])=>({...x,...ps.find(p=>p.id===id)})).sort((a,b)=>b.qty-a.qty).slice(0,6)}
</script>

{#if !ready}<div class="boot"><HeartPulse size={34}/><b>MedikaPOS</b><span>Membuka database lokal…</span></div>{:else if !loggedIn}<main class="login"><div class="login-left"><div class="brand"><span class="brand-icon"><HeartPulse size={22}/></span><div><b>MedikaPOS</b><small>MEDICAL SUPPLIES MANAGEMENT</small></div></div><div class="login-copy"><span class="eyebrow">RETAIL INVENTORY, MADE CLEAR</span><h1>Kelola perlengkapan medis dengan tenang.</h1><p>Demo POS lokal untuk toko alat kesehatan, klinik, dan supplier. Produk, batch, nomor seri, dan transaksi dalam satu alur.</p></div><div class="login-foot">Data tersimpan di browser ini · tidak tersinkron antar perangkat</div></div><div class="login-right"><div class="login-box"><div class="login-mobile brand"><span class="brand-icon"><HeartPulse size={22}/></span><div><b>MedikaPOS</b><small>DEMO RETAIL SYSTEM</small></div></div><span class="eyebrow">AKSES DEMO</span><h2>Selamat datang</h2><p>Pilih peran untuk membuka demo. Kata sandi: <b>demo123</b></p><label class="field">Nama pengguna<input id="login-user" value={role} oninput={(e)=>role=(e.currentTarget as HTMLInputElement).value} placeholder="owner atau cashier"/></label><label class="field">Kata sandi<input type="password" value="demo123" id="login-pass"/></label><button class="button primary full" onclick={()=>{const pw=(document.getElementById('login-pass') as HTMLInputElement).value;if(pw!=='demo123')return notify('Kata sandi demo tidak sesuai.');const who=(document.getElementById('login-user') as HTMLInputElement).value.trim().toLowerCase();if(!['owner','cashier'].includes(who))return notify('Gunakan owner atau cashier.');login(who)}}>Masuk ke demo <span>→</span></button><div class="demo-account"><span><b>OWNER</b><small>Semua modul</small></span><button onclick={()=>role='owner'}>Pilih owner</button></div><div class="demo-account"><span><b>KASIR</b><small>POS & riwayat</small></span><button onclick={()=>role='cashier'}>Pilih kasir</button></div><small class="local-note">Login simulasi frontend. Bukan autentikasi produksi.</small></div></div>{#if notice}<div class="toast"><AlertTriangle size={16}/>{notice}</div>{/if}</main>
{:else}
<div class:sidebar-closed={!sidebar} class:sidebar-open-mobile={menuMobile} class="app-shell">
 <aside class="sidebar"><div class="brand"><span class="brand-icon"><HeartPulse size={21}/></span><div><b>MedikaPOS</b><small>MEDICAL SUPPLIES</small></div><button class="side-collapse" aria-label="Ciutkan menu" onclick={()=>sidebar=false}><Menu size={17}/></button></div><div class="store-switch"><span class="store-dot">MS</span><span><b>Medika Sehat Supply</b><small>Retail · Jakarta</small></span><ChevronDown size={14}/></div><nav>{#each shownNav as group}<div class="nav-group"><div class="nav-label">{group.title}</div>{#each group.items as item}<button class:active={page===item} class="nav-item" aria-current={page===item?'page':undefined} onclick={()=>{page=item;query='';menuMobile=false}}><svelte:component this={group.icon} size={17}/><span>{item}</span>{#if item==='Kasir / POS'}<kbd>F2</kbd>{/if}</button>{/each}</div>{/each}</nav><div class="sidebar-bottom"><div class="demo-chip"><span class="pulse"></span>MODE DEMO · DATA LOKAL</div><div class="profile"><div class="avatar">{role==='owner'?'OW':'KA'}</div><span><b>{role==='owner'?'Demo Owner':'Demo Kasir'}</b><small>{role==='owner'?'Administrator':'Kasir'}</small></span><button aria-label="Keluar" onclick={logout}><LogOut size={16}/></button></div></div></aside>
 <main class="main"><header class="topbar"><div class="top-left"><button class="mobile-menu" aria-label="Buka menu" onclick={()=>menuMobile=!menuMobile}><Menu size={19}/></button><div><div class="breadcrumbs">MedikaPOS <span>/</span> <b>{title(page)}</b></div><h1>{title(page)}</h1></div></div><div class="top-actions"><div class="today"><CalendarClock size={15}/>{new Date().toLocaleDateString('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</div><button class="icon-button" title="Pemberitahuan stok"><Activity size={17}/>{#if lowStock.length}<i>{lowStock.length}</i>{/if}</button><div class="top-avatar">{role==='owner'?'OW':'KA'}</div></div></header><div class="demo-banner"><span><ShieldCheck size={15}/> MODE DEMO — DATA TERSIMPAN LOKAL DI BROWSER INI</span><button onclick={exportBackup}><Download size={14}/> Backup data</button></div>
 <section class="content">
 {#if page==='Overview'}
 <div class="welcome"><div><div class="eyebrow">SENIN · OPERASIONAL TOKO</div><h2>Selamat datang, {role==='owner'?'Owner':'Kasir'}.</h2><p>Ringkasan toko Anda hari ini, langsung dari database lokal.</p></div><button class="button primary" onclick={()=>page='Kasir / POS'}><ShoppingCart size={16}/> Buka kasir <span>→</span></button></div>
 <div class="metrics"><article class="metric metric-feature"><div class="metric-top"><span>Penjualan hari ini</span><span class="metric-icon teal"><Wallet size={17}/></span></div><strong>{rupiah(revenue)}</strong><small>{todayCount} transaksi tercatat</small></article><article class="metric"><div class="metric-top"><span>Produk aktif</span><span class="metric-icon blue"><Package size={17}/></span></div><strong>{products.filter(p=>p.active).length}</strong><small>{products.length} SKU terdaftar</small></article><article class="metric"><div class="metric-top"><span>Nilai persediaan</span><span class="metric-icon sand"><Boxes size={17}/></span></div><strong>{rupiah(inventoryValue)}</strong><small>{Object.values(stock).reduce((a,n)=>a+n,0)} unit tersedia</small></article><article class="metric"><div class="metric-top"><span>Perlu perhatian</span><span class="metric-icon rose"><AlertTriangle size={17}/></span></div><strong>{lowStock.length+expiring.length+expired.length}</strong><small>{lowStock.length} stok rendah · {expiring.length} near expiry</small></article></div>
 <div class="overview-grid"><article class="panel sales-panel"><div class="panel-head"><div><h3>Aktivitas penjualan</h3><p>Transaksi tersimpan dalam database</p></div><button class="link-button" onclick={()=>page='Laporan'}>Lihat laporan <span>→</span></button></div>{#if sales.length}<div class="chart"><div class="chart-guides"><span>Rp 1 jt</span><span>Rp 500 rb</span><span>Rp 0</span></div><div class="chart-bars">{#each lastSevenDays(sales) as day}<div class="bar-col"><div class="bar" style={`height:${Math.max(4,day.total?day.total/Math.max(1,...lastSevenDays(sales).map(d=>d.total))*100:2)}%`} title={rupiah(day.total)}></div><small>{day.label}</small></div>{/each}</div></div>{:else}<div class="empty-chart"><ChartNoAxesCombined size={27}/><b>Belum ada transaksi</b><span>Mulai dari kasir untuk membentuk ringkasan penjualan.</span><button class="link-button" onclick={()=>page='Kasir / POS'}>Buka kasir →</button></div>{/if}</article>
 <article class="panel attention-panel"><div class="panel-head"><div><h3>Perlu diperiksa</h3><p>Stok dan masa berlaku</p></div><button class="icon-button" aria-label="Refresh" onclick={refresh}><RefreshCw size={15}/></button></div>{#if lowStock.length||expiring.length||expired.length}<div class="attention-list">{#each lowStock.slice(0,3) as p}<button class="attention-row" onclick={()=>{page='Stok Barang';query=p.name}}><span class="attention-icon warning"><Boxes size={15}/></span><span><b>{p.name}</b><small>Stok {stock[p.id]||0} · minimum {p.minimum}</small></span><span class="status-pill warn">Stok rendah</span></button>{/each}{#each expiring.slice(0,3) as b}<button class="attention-row" onclick={()=>page='Batch & Expiry'}><span class="attention-icon blue"><CalendarClock size={15}/></span><span><b>{products.find(p=>p.id===b.productId)?.name||'Produk'}</b><small>Batch {b.batchNumber} · {b.expiry}</small></span><span class="status-pill blue-pill">Near expiry</span></button>{/each}{#each expired.slice(0,2) as b}<button class="attention-row" onclick={()=>page='Batch & Expiry'}><span class="attention-icon danger"><AlertTriangle size={15}/></span><span><b>{products.find(p=>p.id===b.productId)?.name||'Produk'}</b><small>Batch {b.batchNumber} · {b.expiry}</small></span><span class="status-pill danger-pill">Expired</span></button>{/each}</div>{:else}<div class="quiet-empty"><Check size={20}/><span>Tidak ada peringatan aktif saat ini.</span></div>{/if}</article></div>
 <article class="panel recent-panel"><div class="panel-head"><div><h3>Transaksi terbaru</h3><p>Riwayat penjualan demo</p></div><button class="link-button" onclick={()=>page='Riwayat Penjualan'}>Semua transaksi <span>→</span></button></div>{#if sales.length}<div class="table-wrap"><table><thead><tr><th>NO. TRANSAKSI</th><th>WAKTU</th><th>PELANGGAN</th><th>ITEM</th><th>PEMBAYARAN</th><th class="right">TOTAL</th></tr></thead><tbody>{#each sales.slice(0,5) as s}<tr><td><b class="mono">{s.number}</b></td><td>{date(s.date)}</td><td>{s.customer}</td><td>{s.items.reduce((n,i)=>n+i.qty,0)} unit</td><td><span class="pay-badge">{s.payment}</span></td><td class="right"><b>{rupiah(s.total)}</b></td></tr>{/each}</tbody></table></div>{:else}<div class="empty-inline">Transaksi akan muncul setelah penjualan pertama.</div>{/if}</article>
 {:else if page==='Produk'}
 <div class="page-intro"><div><h2>Katalog produk</h2><p>Kelola SKU, harga, dan jenis pelacakan persediaan.</p></div><button class="button primary" onclick={openNew}><Plus size={16}/> Tambah produk</button></div><div class="panel table-panel"><div class="toolbar"><label class="search"><Search size={16}/><input bind:value={query} placeholder="Cari nama, SKU, barcode, merek…" aria-label="Cari produk"/></label><select bind:value={categoryFilter} aria-label="Filter kategori"><option value="all">Semua kategori</option>{#each categories as c}<option value={c.id}>{c.name}</option>{/each}</select><span class="count">{filtered.length} produk</span></div><div class="table-wrap"><table><thead><tr><th>PRODUK</th><th>KATEGORI / MEREK</th><th>TRACKING</th><th>STOK</th><th>HARGA JUAL</th><th>STATUS</th><th></th></tr></thead><tbody>{#each filtered as p}<tr><td><div class="product-info"><span class="product-symbol">{#if p.tracking==='BATCH'}<Barcode size={17}/>{:else if p.tracking==='SERIAL'}<Activity size={17}/>{:else}<Package size={17}/>{/if}</span><span><b>{p.name}</b><small>{p.sku} · {p.barcode}</small></span></div></td><td>{productCategory(p)}<small class="subline">{productBrand(p)}</small></td><td><span class="tracking-pill {p.tracking.toLowerCase()}">{p.tracking}</span></td><td><b>{stock[p.id]??'—'}</b> <small>{p.unit}</small></td><td><b>{rupiah(p.price)}</b><small class="subline">Modal {rupiah(p.cost)}</small></td><td><span class="status-pill {stock[p.id]===0?'danger-pill':stock[p.id]<=p.minimum?'warn':'good'}">{stock[p.id]===0?'Habis':stock[p.id]<=p.minimum?'Menipis':'Aktif'}</span></td><td class="actions"><button aria-label="Edit produk" class="icon-button" onclick={()=>openEdit(p)}><Eye size={15}/></button><button aria-label="Hapus produk" class="icon-button" onclick={()=>removeProduct(p)}><Trash2 size={15}/></button></td></tr>{/each}</tbody></table>{#if !filtered.length}<div class="empty-inline">Tidak ada produk yang cocok dengan pencarian.</div>{/if}</div></div>
 {:else if page==='Kasir / POS'}
 <div class="pos-layout"><section class="pos-catalog"><div class="pos-toolbar"><label class="search"><Search size={16}/><input bind:value={query} placeholder="Cari produk atau scan barcode…" aria-label="Cari atau scan produk" onkeydown={(e)=>{if(e.key==='Enter'){const p=products.find(x=>x.barcode===query||x.sku.toLowerCase()===query.toLowerCase());if(p){addToCart(p);query=''}}}}/></label><select bind:value={categoryFilter} aria-label="Filter kategori"><option value="all">Semua kategori</option>{#each categories as c}<option value={c.id}>{c.name}</option>{/each}</select></div><div class="pos-categories"><button class:chosen={categoryFilter==='all'} onclick={()=>categoryFilter='all'}>Semua</button>{#each categories.slice(0,5) as c}<button class:chosen={categoryFilter===c.id} onclick={()=>categoryFilter=c.id}>{c.name}</button>{/each}</div><div class="product-grid">{#each filtered as p}<button class="pos-product" disabled={!stock[p.id]} onclick={()=>addToCart(p)}><span class="pos-icon">{#if p.tracking==='BATCH'}<Barcode size={18}/>{:else if p.tracking==='SERIAL'}<Activity size={18}/>{:else}<Package size={18}/>{/if}</span><span class="available" class:low={(stock[p.id]||0)<=p.minimum}>{stock[p.id]||0} {p.unit}</span><b>{p.name}</b><small>{p.sku} · {p.tracking}</small><strong>{rupiah(p.price)}</strong></button>{/each}</div></section><aside class="cart-panel"><div class="cart-heading"><div><span class="cart-icon"><ShoppingCart size={17}/></span><span><b>Keranjang</b><small>{itemCount} item dipilih</small></span></div><button class="icon-button" aria-label="Kosongkan keranjang" onclick={()=>cart=[]}><Trash2 size={15}/></button></div><div class="cart-customer"><span class="cart-customer-label">Pelanggan</span><select bind:value={selectedCustomer}><option value="">Pelanggan Umum</option>{#each customers as c}<option value={c.name}>{c.name}</option>{/each}</select></div><div class="cart-list">{#if cart.length}{#each cart as item}<div class="cart-item"><div class="cart-item-top"><span><b>{item.product.name}</b><small>{rupiah(item.product.price)} · {item.product.tracking}</small></span><b>{rupiah(item.product.price*item.qty)}</b></div>{#if item.product.tracking==='SERIAL'}<div class="serial-selects">{#each Array(item.qty) as _,i}<select value={item.serialIds[i]||''} aria-label={`Pilih serial unit ${i+1}`} onchange={(e)=>chooseSerial(item,(e.currentTarget as HTMLSelectElement).value,i)}><option value="">Pilih serial unit {i+1}</option>{#each serials.filter(s=>s.productId===item.product.id&&s.status==='AVAILABLE') as s}<option value={s.id} disabled={item.serialIds.includes(s.id)&&item.serialIds[i]!==s.id}>{s.serial}</option>{/each}</select>{/each}</div>{/if}<div class="qty-line"><button aria-label="Kurangi jumlah" onclick={()=>changeQty(item.product,-1)}><Minus size={13}/></button><b>{item.qty}</b><button aria-label="Tambah jumlah" onclick={()=>changeQty(item.product,1)}><Plus size={13}/></button><button class="remove" aria-label="Hapus item" onclick={()=>cart=cart.filter(x=>x!==item)}><Trash2 size={14}/></button></div></div>{/each}{:else}<div class="cart-empty"><ShoppingCart size={25}/><b>Belum ada produk</b><span>Pilih produk untuk memulai transaksi.</span></div>{/if}</div><div class="cart-total"><div><span>Subtotal</span><b>{rupiah(subtotal)}</b></div><label class="discount-input"><span>Diskon (Rp)</span><input type="number" min="0" max={subtotal} bind:value={discount} aria-label="Diskon transaksi"/></label><div class="grand-total"><b>Total</b><strong>{rupiah(total)}</strong></div><button class="button primary full checkout-button" disabled={!cart.length} onclick={payNow}>Lanjut pembayaran <span>→</span></button><small class="safe-note"><ShieldCheck size={13}/> Stok diverifikasi kembali saat checkout</small></div></aside></div>
 {:else if page==='Stok Barang'}
 <div class="page-intro"><div><h2>Stok barang</h2><p>Saldo quantity dan status ketersediaan yang dapat dijual.</p></div><button class="button secondary" onclick={()=>showPurchase=true}><ArrowDownToLine size={16}/> Terima stok</button></div><div class="metrics compact"><article class="metric"><span>Total unit tersedia</span><strong>{Object.values(stock).reduce((a,n)=>a+n,0)}</strong></article><article class="metric"><span>Stok menipis</span><strong>{lowStock.length}</strong></article><article class="metric"><span>Batch mendekati expiry</span><strong>{expiring.length}</strong></article><article class="metric"><span>Expired</span><strong>{expired.length}</strong></article></div><div class="panel table-panel"><div class="toolbar"><label class="search"><Search size={16}/><input bind:value={query} placeholder="Cari produk atau SKU…" aria-label="Cari stok"/></label><span class="count">Saldo per produk</span></div><div class="table-wrap"><table><thead><tr><th>PRODUK</th><th>JENIS TRACKING</th><th>TERSEDIA</th><th>STOK MINIMUM</th><th>NILAI MODAL</th><th>LOKASI</th><th></th></tr></thead><tbody>{#each filtered as p}<tr><td><b>{p.name}</b><small class="subline">{p.sku}</small></td><td><span class="tracking-pill {p.tracking.toLowerCase()}">{p.tracking}</span></td><td><b>{stock[p.id]||0}</b> {p.unit}</td><td>{p.minimum}</td><td>{rupiah((stock[p.id]||0)*p.cost)}</td><td>Gudang / Rak A</td><td><button class="button tiny secondary" onclick={()=>adjust(p)}>Penyesuaian</button></td></tr>{/each}</tbody></table></div></div>
 {:else if page==='Batch & Expiry'}
 <div class="page-intro"><div><h2>Batch & tanggal kedaluwarsa</h2><p>Stok jual batch menerapkan FEFO dan mengecualikan batch expired.</p></div><div class="intro-actions"><label class="inline-filter">Ambang <select bind:value={expiryFilter}><option value={7}>7 hari</option><option value={30}>30 hari</option><option value={60}>60 hari</option><option value={90}>90 hari</option></select></label><button class="button primary" onclick={()=>showPurchase=true}><Plus size={16}/> Penerimaan batch</button></div></div><div class="metrics compact"><article class="metric"><span>Batch tercatat</span><strong>{batches.length}</strong></article><article class="metric"><span>Stok batch aktif</span><strong>{batches.filter(b=>b.status==='ACTIVE'&&b.expiry>=new Date().toISOString().slice(0,10)).reduce((a,b)=>a+b.remaining,0)}</strong></article><article class="metric"><span>Mendekati expiry</span><strong class="text-warning">{expiring.length}</strong></article><article class="metric"><span>Expired</span><strong class="text-danger">{expired.length}</strong></article></div><div class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>PRODUK / BATCH</th><th>NO. LOT</th><th>TGL KEDALUWARSA</th><th>SISA</th><th>STATUS</th><th></th></tr></thead><tbody>{#each batches as b}<tr><td><b>{products.find(p=>p.id===b.productId)?.name||'Produk'}</b><small class="subline">{b.batchNumber}</small></td><td>{b.lotNumber||'—'}</td><td>{b.expiry}</td><td><b>{b.remaining}</b> unit</td><td><span class="status-pill {b.status==='QUARANTINED'||b.status==='RECALLED'?'danger-pill':b.expiry<new Date().toISOString().slice(0,10)?'danger-pill':new Date(b.expiry).getTime()-Date.now()<expiryFilter*86400000?'warn':'good'}">{b.status==='ACTIVE'?(b.expiry<new Date().toISOString().slice(0,10)?'Expired':new Date(b.expiry).getTime()-Date.now()<expiryFilter*86400000?'Near expiry':'Aktif'):b.status}</span></td><td>{#if b.status==='ACTIVE'}<button class="button tiny secondary" onclick={async()=>{await db.batches.update(b.id,{status:'QUARANTINED'});await refresh();notify('Batch dikarantina dan tidak dapat dijual.')}}>Karantina</button>{:else}<span class="subline">Tidak untuk dijual</span>{/if}</td></tr>{/each}</tbody></table>{#if !batches.length}<div class="empty-inline">Belum ada batch. Buat pembelian untuk menerima batch.</div>{/if}</div></div>
 {:else if page==='Serial Number'}
 <div class="page-intro"><div><h2>Unit serial</h2><p>Identitas unit, status penjualan, dan masa garansi.</p></div><button class="button secondary" onclick={()=>showPurchase=true}><Plus size={16}/> Terima unit serial</button></div><div class="panel table-panel"><div class="toolbar"><label class="search"><Search size={16}/><input bind:value={query} placeholder="Cari serial, SKU, atau produk…" aria-label="Cari nomor seri"/></label><span class="count">{serials.length} unit</span></div><div class="table-wrap"><table><thead><tr><th>PRODUK</th><th>NOMOR SERI</th><th>STATUS</th><th>MASA GARANSI</th><th>PELANGGAN</th></tr></thead><tbody>{#each serials.filter(s=>`${s.serial} ${products.find(p=>p.id===s.productId)?.name||''}`.toLowerCase().includes(query.toLowerCase())) as s}<tr><td><b>{products.find(p=>p.id===s.productId)?.name||'Produk'}</b><small class="subline">{products.find(p=>p.id===s.productId)?.sku}</small></td><td class="mono">{s.serial}</td><td><span class="status-pill {s.status==='AVAILABLE'?'good':s.status==='SOLD'?'blue-pill':'warn'}">{s.status}</span></td><td>{s.warrantyEnd||`${s.warrantyMonths} bulan dari penjualan`}</td><td>{s.customer||'—'}</td></tr>{/each}</tbody></table></div></div>
 {:else if page==='Pembelian'}
 <div class="page-intro"><div><h2>Pembelian supplier</h2><p>Penerimaan pembelian memperbarui stok dan menyimpan harga modal historis.</p></div><button class="button primary" onclick={()=>{purchaseProduct=products[0]?.id||'';purchaseSupplier=suppliers[0]?.id||'';purchaseQty=1;purchaseCost=products[0]?.cost||0;purchaseBatch='';purchaseLot='';purchaseExpiry='';purchaseSerials='';showPurchase=true}}><Plus size={16}/> Catat pembelian</button></div><div class="metrics compact"><article class="metric"><span>Jumlah pembelian</span><strong>{purchases.length}</strong></article><article class="metric"><span>Nilai pembelian</span><strong>{rupiah(purchases.reduce((a,p)=>a+p.total,0))}</strong></article><article class="metric"><span>Supplier aktif</span><strong>{suppliers.filter(s=>s.active).length}</strong></article></div><div class="panel table-panel"><div class="table-wrap"><table><thead><tr><th>NO. PEMBELIAN</th><th>TANGGAL</th><th>SUPPLIER</th><th>BARANG</th><th class="right">TOTAL</th></tr></thead><tbody>{#each purchases as p}<tr><td class="mono"><b>{p.number}</b></td><td>{date(p.date)}</td><td>{p.supplier}</td><td>{p.items.map(i=>`${i.name} (${i.quantity})`).join(', ')}</td><td class="right"><b>{rupiah(p.total)}</b></td></tr>{/each}</tbody></table>{#if !purchases.length}<div class="empty-inline">Belum ada pembelian yang tercatat.</div>{/if}</div></div>
 {:else if page==='Riwayat Penjualan'}
 <div class="page-intro"><div><h2>Riwayat penjualan</h2><p>Transaksi tidak dihapus permanen. Cetak ulang nota dari detail transaksi.</p></div><button class="button secondary" onclick={()=>csvDownload([['Nomor','Tanggal','Pelanggan','Subtotal','Diskon','Total','Status'],...sales.map(s=>[s.number,s.date,s.customer,s.subtotal,s.discount,s.total,s.status])],'medikapos-penjualan.csv')}><Download size={15}/> Ekspor CSV</button></div><div class="panel table-panel"><div class="toolbar"><label class="search"><Search size={16}/><input bind:value={query} placeholder="Cari nomor transaksi atau pelanggan…" aria-label="Cari transaksi"/></label><span class="count">{sales.length} transaksi</span></div><div class="table-wrap"><table><thead><tr><th>NO. TRANSAKSI</th><th>TANGGAL</th><th>PELANGGAN</th><th>KASIR</th><th>METODE</th><th>STATUS</th><th class="right">TOTAL</th><th></th></tr></thead><tbody>{#each sales.filter(s=>`${s.number} ${s.customer}`.toLowerCase().includes(query.toLowerCase())) as s}<tr><td class="mono"><b>{s.number}</b></td><td>{date(s.date)}</td><td>{s.customer}</td><td>{s.cashier}</td><td>{s.payment}</td><td><span class="status-pill {s.status==='COMPLETED'?'good':'danger-pill'}">{s.status}</span></td><td class="right"><b>{rupiah(s.total)}</b></td><td><button class="icon-button" aria-label="Cetak nota" onclick={()=>showReceipt=s}><Printer size={15}/></button></td></tr>{/each}</tbody></table></div></div>
 {:else if page==='Kategori'||page==='Merek'}
 {@const list=page==='Kategori'?categories:brands}{@const label=page==='Kategori'?'Kategori':'Merek'}<div class="page-intro"><div><h2>{label} produk</h2><p>Daftar nilai referensi katalog, tersimpan di IndexedDB.</p></div><button class="button primary" onclick={()=>{masterKind=label;masterName='';showMaster=true}}><Plus size={16}/> Tambah {label.toLowerCase()}</button></div><div class="master-grid">{#each list as item}<article class="master-card"><span class="master-icon">{#if page==='Kategori'}<Tag size={18}/>{:else}<Package size={18}/>{/if}</span><div><b>{item.name}</b><small>{page==='Kategori'?products.filter(p=>p.categoryId===item.id).length:products.filter(p=>p.brandId===item.id).length} produk terhubung</small></div><span class="status-pill good">Aktif</span></article>{/each}</div>
 {:else if page==='Supplier'}
 <div class="page-intro"><div><h2>Supplier</h2><p>Kontak pemasok serta riwayat penerimaan barang.</p></div><button class="button primary" onclick={()=>showSupplier=true}><Plus size={16}/> Tambah supplier</button></div><div class="master-grid">{#each suppliers as s}<article class="master-card"><span class="master-icon"><Truck size={18}/></span><div><b>{s.name}</b><small>{s.phone||'Nomor telepon belum diisi'} · {purchases.filter(p=>p.supplierId===s.id).length} pembelian</small></div><span class="status-pill good">Aktif</span></article>{/each}</div>
 {:else if page==='Pelanggan'}
 <div class="page-intro"><div><h2>Pelanggan</h2><p>Catat pelanggan retail dan institusi tanpa data pasien.</p></div><button class="button primary" onclick={()=>showCustomer=true}><Plus size={16}/> Tambah pelanggan</button></div><div class="panel table-panel"><div class="toolbar"><label class="search"><Search size={16}/><input bind:value={query} placeholder="Cari nama, tipe, atau institusi…" aria-label="Cari pelanggan"/></label></div><div class="table-wrap"><table><thead><tr><th>NAMA</th><th>JENIS</th><th>INSTITUSI</th><th>TELEPON</th><th>TRANSAKSI</th><th>TOTAL PEMBELIAN</th></tr></thead><tbody>{#each customers.filter(c=>`${c.name} ${c.type} ${c.institution}`.toLowerCase().includes(query.toLowerCase())) as c}<tr><td><b>{c.name}</b></td><td><span class="pay-badge">{c.type}</span></td><td>{c.institution||'—'}</td><td>{c.phone||'—'}</td><td>{sales.filter(s=>s.customer===c.name).length}</td><td><b>{rupiah(sales.filter(s=>s.customer===c.name&&s.status==='COMPLETED').reduce((a,s)=>a+s.total,0))}</b></td></tr>{/each}</tbody></table></div></div>
 {:else if page==='Laporan'}
 <div class="page-intro"><div><h2>Laporan operasional</h2><p>Angka dihitung dari transaksi, penerimaan, dan stok lokal.</p></div><button class="button secondary" onclick={()=>csvDownload([['SKU','Produk','Kategori','Stok','Modal/unit','Nilai stok'],...products.map(p=>[p.sku,p.name,productCategory(p),stock[p.id]||0,p.cost,(stock[p.id]||0)*p.cost])],'medikapos-laporan-inventory.csv')}><Download size={15}/> Ekspor stok CSV</button></div><div class="metrics"><article class="metric"><span>Omzet bersih tercatat</span><strong>{rupiah(sales.filter(s=>s.status==='COMPLETED').reduce((a,s)=>a+s.total,0))}</strong><small>{sales.filter(s=>s.status==='COMPLETED').length} transaksi selesai</small></article><article class="metric"><span>Total pembelian</span><strong>{rupiah(purchases.reduce((a,p)=>a+p.total,0))}</strong><small>{purchases.length} penerimaan</small></article><article class="metric"><span>Nilai persediaan</span><strong>{rupiah(inventoryValue)}</strong><small>Estimasi berdasarkan modal terakhir</small></article><article class="metric"><span>Estimasi keuntungan demo</span><strong>{rupiah(sales.filter(s=>s.status==='COMPLETED').reduce((a,s)=>a+s.items.reduce((b,i)=>b+(i.price-i.cost)*i.qty,0)-s.discount,0))}</strong><small>Perkiraan dari harga modal tersimpan</small></article></div><div class="overview-grid"><article class="panel sales-panel"><div class="panel-head"><div><h3>Penjualan per hari</h3><p>7 hari berjalan · {rupiah(lastSevenDays(sales).reduce((a,d)=>a+d.total,0))}</p></div></div><div class="chart report-chart"><div class="chart-guides"><span>100%</span><span>50%</span><span>0%</span></div><div class="chart-bars">{#each lastSevenDays(sales) as day}<div class="bar-col"><div class="bar" style={`height:${Math.max(3,day.total?day.total/Math.max(1,...lastSevenDays(sales).map(d=>d.total))*100:2)}%`}></div><small>{day.label}</small></div>{/each}</div></div></article><article class="panel"><div class="panel-head"><div><h3>Komposisi stok</h3><p>Jumlah unit berdasarkan tracking</p></div></div><div class="report-breakdown">{#each ['QUANTITY','BATCH','SERIAL'] as t}<div><span><i class={`dot ${t.toLowerCase()}`}></i>{t}</span><b>{products.filter(p=>p.tracking===t).reduce((a,p)=>a+(stock[p.id]||0),0)} unit</b></div>{/each}</div></article></div><article class="panel recent-panel"><div class="panel-head"><div><h3>Produk terlaris</h3><p>Akumulasi qty dari penjualan selesai</p></div></div><div class="table-wrap"><table><thead><tr><th>PRODUK</th><th>SKU</th><th>UNIT TERJUAL</th><th>OMZET</th></tr></thead><tbody>{#each bestSellers(sales,products) as row}<tr><td><b>{row.name}</b></td><td>{row.sku}</td><td>{row.qty}</td><td><b>{rupiah(row.revenue)}</b></td></tr>{/each}</tbody></table></div></article>
 {:else if page==='Pengaturan'}
 <div class="page-intro"><div><h2>Pengaturan & data demo</h2><p>Preferensi toko dan salinan database browser lokal.</p></div></div><div class="settings-grid"><article class="panel settings-card"><div class="panel-head"><div><h3>Profil toko</h3><p>Informasi yang digunakan pada nota.</p></div><Building2 size={18}/></div><label class="field">Nama toko<input id="store-name" value="Medika Sehat Supply"/></label><label class="field">Alamat<input id="store-address" value="Jl. Kesehatan, Jakarta"/></label><label class="field">Telepon<input id="store-phone" value="021 555 0100"/></label><label class="field">Ambang near expiry<select bind:value={expiryFilter}><option value={7}>7 hari</option><option value={30}>30 hari</option><option value={60}>60 hari</option><option value={90}>90 hari</option></select></label><button class="button primary" onclick={async()=>{await db.settings.put({id:'store',value:{name:(document.getElementById('store-name') as HTMLInputElement).value,address:(document.getElementById('store-address') as HTMLInputElement).value,phone:(document.getElementById('store-phone') as HTMLInputElement).value,expiryDays:Number(expiryFilter)}});localStorage.setItem('medikapos-expiry',String(expiryFilter));notify('Pengaturan toko tersimpan')}}><Check size={15}/> Simpan pengaturan</button></article><article class="panel settings-card"><div class="panel-head"><div><h3>Backup & pemulihan</h3><p>Ekspor semua tabel IndexedDB sebagai JSON.</p></div><Archive size={18}/></div><div class="setting-row"><div><b>Unduh backup lengkap</b><small>Produk, stok, batch, serial, transaksi, dan pengaturan.</small></div><button class="button secondary" onclick={exportBackup}><Download size={15}/> Backup</button></div><div class="setting-row"><div><b>Restore dari JSON</b><small>Data lokal yang cocok akan diganti oleh file backup.</small></div><label class="button secondary upload-button"><Upload size={15}/> Pilih file<input type="file" accept="application/json,.json" onchange={(e)=>{const f=(e.currentTarget as HTMLInputElement).files?.[0];if(f)importBackup(f)}}/></label></div><div class="setting-row"><div><b>Ekspor produk CSV</b><small>Daftar SKU, kategori, harga, dan saldo.</small></div><button class="button secondary" onclick={()=>csvDownload([['SKU','Nama','Kategori','Merek','Tracking','Stok','Harga Modal','Harga Jual'],...products.map(p=>[p.sku,p.name,productCategory(p),productBrand(p),p.tracking,stock[p.id]||0,p.cost,p.price])],'medikapos-produk.csv')}><Download size={15}/> CSV</button></div><div class="reset-row"><span><b>Pulihkan data demo</b><small>Mengganti seluruh data browser dengan seed awal.</small></span><button class="button danger-button" onclick={resetDemo}><RotateCcw size={15}/> Reset demo</button></div></article></div><div class="disclaimer"><AlertTriangle size={17}/><span><b>Demo retail frontend</b> · Data hanya tersimpan di browser ini, tidak tersinkron antar perangkat. Informasi registrasi demo belum diverifikasi. Jangan masukkan data pasien atau informasi kesehatan.</span></div>
 {/if}
 </section><footer class="footer"><span>MedikaPOS <b>·</b> Demo retail alat kesehatan</span><span>IndexedDB lokal <i class="footer-dot"></i> Sesi {role==='owner'?'Owner':'Kasir'}</span></footer></main></div>
{/if}

{#if showProduct}<div class="overlay" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)showProduct=false}}><div class="modal" role="dialog" aria-modal="true" aria-labelledby="product-title"><div class="modal-head"><div><span class="eyebrow">KATALOG INVENTORY</span><h2 id="product-title">{editing?'Edit produk':'Tambah produk'}</h2><p>SKU tetap menjadi identitas unik produk.</p></div><button class="icon-button" aria-label="Tutup" onclick={()=>showProduct=false}><X size={17}/></button></div><div class="form-grid"><label>SKU *<input bind:value={form.sku} placeholder="AL-011"/></label><label>Barcode<input bind:value={form.barcode} placeholder="Scan atau isi manual"/></label><label class="wide">Nama produk *<input bind:value={form.name} placeholder="Nama produk"/></label><label>Kategori<select bind:value={form.categoryId}>{#each categories as c}<option value={c.id}>{c.name}</option>{/each}</select></label><label>Merek<select bind:value={form.brandId}>{#each brands as b}<option value={b.id}>{b.name}</option>{/each}</select></label><label>Tracking<select bind:value={form.tracking} disabled={!!editing&&products.some(p=>p.id===editing?.id&&stock[p.id]>0)}><option value="QUANTITY">Quantity</option><option value="BATCH">Batch & expiry</option><option value="SERIAL">Serial number</option></select></label><label>Satuan dasar<input bind:value={form.unit} placeholder="PCS"/></label><label>Harga modal (Rp)<input type="number" min="0" bind:value={form.cost}/></label><label>Harga jual (Rp)<input type="number" min="0" bind:value={form.price}/></label><label>Stok minimum<input type="number" min="0" bind:value={form.minimum}/></label><label>Produsen<input bind:value={form.manufacturer}/></label><label class="wide">Deskripsi<textarea bind:value={form.description} rows="2"></textarea></label>{#if !editing}<label class="wide">Stok awal<input type="number" min="0" value="0" disabled/><small class="form-hint">Catat stok awal melalui menu Pembelian agar batch, serial, dan histori stok konsisten.</small></label>{/if}</div><div class="modal-actions"><button class="button secondary" onclick={()=>showProduct=false}>Batal</button><button class="button primary" onclick={persistProduct}><Check size={15}/> Simpan produk</button></div></div></div>{/if}

{#if showPurchase}<div class="overlay" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)showPurchase=false}}><div class="modal" role="dialog" aria-modal="true" aria-labelledby="purchase-title"><div class="modal-head"><div><span class="eyebrow">STOK MASUK</span><h2 id="purchase-title">Penerimaan pembelian</h2><p>Stok masuk dan histori tersimpan dalam satu transaksi.</p></div><button class="icon-button" aria-label="Tutup" onclick={()=>showPurchase=false}><X size={17}/></button></div><div class="form-grid"><label class="wide">Supplier<select bind:value={purchaseSupplier}><option value="">Pilih supplier</option>{#each suppliers as s}<option value={s.id}>{s.name}</option>{/each}</select></label><label class="wide">Produk<select bind:value={purchaseProduct} onchange={()=>{const p=products.find(x=>x.id===purchaseProduct);if(p)purchaseCost=p.cost}}><option value="">Pilih produk</option>{#each products.filter(p=>p.active) as p}<option value={p.id}>{p.sku} — {p.name} ({p.tracking})</option>{/each}</select></label><label>Jumlah unit<input type="number" min="1" step="1" bind:value={purchaseQty}/></label><label>Harga modal / unit (Rp)<input type="number" min="0" bind:value={purchaseCost}/></label>{#if products.find(p=>p.id===purchaseProduct)?.tracking==='BATCH'}<label>Nomor batch *<input bind:value={purchaseBatch} placeholder="BATCH-2026-01"/></label><label>Nomor lot<input bind:value={purchaseLot}/></label><label class="wide">Tanggal kedaluwarsa *<input type="date" bind:value={purchaseExpiry}/></label>{/if}{#if products.find(p=>p.id===purchaseProduct)?.tracking==='SERIAL'}<label class="wide">Nomor seri * (satu per baris atau koma)<textarea rows="3" bind:value={purchaseSerials} placeholder="SN-001, SN-002"></textarea></label>{/if}</div><div class="purchase-total"><span>Nilai penerimaan</span><b>{rupiah((Number(purchaseQty)||0)*(Number(purchaseCost)||0))}</b></div><div class="modal-actions"><button class="button secondary" onclick={()=>showPurchase=false}>Batal</button><button class="button primary" onclick={purchase}><Check size={15}/> Simpan penerimaan</button></div></div></div>{/if}

{#if showCustomer}<div class="overlay"><section class="modal compact-modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>Tambah pelanggan</h2><p>Hindari data pasien atau informasi kesehatan.</p></div><button class="icon-button" aria-label="Tutup" onclick={()=>showCustomer=false}><X size={17}/></button></div><label class="field">Nama pelanggan / institusi<input bind:value={customerName}/></label><label class="field">Jenis<select bind:value={customerType}>{#each ['Individu','Klinik','Rumah sakit','Laboratorium','Praktik dokter','Apotek','Distributor','Institusi lainnya'] as t}<option>{t}</option>{/each}</select></label><label class="field">Nomor telepon (opsional)<input bind:value={customerPhone}/></label><div class="modal-actions"><button class="button secondary" onclick={()=>showCustomer=false}>Batal</button><button class="button primary" onclick={saveCustomer}>Simpan</button></div></section></div>{/if}
{#if showSupplier}<div class="overlay"><section class="modal compact-modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>Tambah supplier</h2><p>Kontak dasar pemasok.</p></div><button class="icon-button" aria-label="Tutup" onclick={()=>showSupplier=false}><X size={17}/></button></div><label class="field">Nama supplier<input bind:value={supplierName}/></label><label class="field">Nomor telepon<input bind:value={supplierPhone}/></label><div class="modal-actions"><button class="button secondary" onclick={()=>showSupplier=false}>Batal</button><button class="button primary" onclick={saveSupplier}>Simpan</button></div></section></div>{/if}
{#if showMaster}<div class="overlay"><section class="modal compact-modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>Tambah {masterKind.toLowerCase()}</h2><p>Nilai ini tersedia untuk katalog produk.</p></div><button class="icon-button" aria-label="Tutup" onclick={()=>showMaster=false}><X size={17}/></button></div><label class="field">Nama {masterKind.toLowerCase()}<input bind:value={masterName}/></label><div class="modal-actions"><button class="button secondary" onclick={()=>showMaster=false}>Batal</button><button class="button primary" onclick={saveMaster}>Simpan</button></div></section></div>{/if}
{#if showPayment}<div class="overlay"><section class="modal compact-modal" role="dialog" aria-modal="true"><div class="modal-head"><div><span class="eyebrow">CHECKOUT</span><h2>Pembayaran</h2><p>Stok diverifikasi dan disimpan secara atomik.</p></div><button class="icon-button" aria-label="Tutup" onclick={()=>showPayment=false}><X size={17}/></button></div><div class="pay-total"><span>Total tagihan</span><b>{rupiah(total)}</b></div><label class="field">Metode pembayaran<select bind:value={payment}>{#each ['Tunai','Transfer bank','QRIS','Debit','Lainnya'] as p}<option>{p}</option>{/each}</select></label><label class="field">Jumlah dibayar (Rp)<input type="number" min={total} bind:value={paid}/></label><div class="change-row"><span>Kembalian</span><b>{rupiah(Math.max(0,Number(paid)-total))}</b></div><div class="modal-actions"><button class="button secondary" onclick={()=>showPayment=false}>Kembali</button><button class="button primary" onclick={finishSale}><Check size={15}/> Selesaikan transaksi</button></div></section></div>{/if}
{#if showReceipt}<div class="overlay receipt-overlay"><section class="receipt-modal"><div class="receipt-tools"><b>Nota {showReceipt.number}</b><div><button class="button secondary tiny" onclick={printReceipt}><Printer size={14}/> Cetak</button><button class="icon-button" aria-label="Tutup nota" onclick={()=>showReceipt=null}><X size={16}/></button></div></div><div class="receipt" id="receipt"><div class="receipt-center"><b>MEDIKA SEHAT SUPPLY</b><span>MEDICAL EQUIPMENT & HEALTHCARE SUPPLIES</span><small>Jl. Kesehatan, Jakarta · 021 555 0100</small></div><hr/><p>No: {showReceipt.number}<br/>Tanggal: {date(showReceipt.date)}<br/>Kasir: {showReceipt.cashier}<br/>Pelanggan: {showReceipt.customer}</p><hr/>{#each showReceipt.items as i}<div class="receipt-line"><span>{i.name}<small>{i.qty} × {rupiah(i.price)}</small></span><b>{rupiah(i.qty*i.price)}</b></div>{/each}<hr/><div class="receipt-line"><span>Subtotal</span><b>{rupiah(showReceipt.subtotal)}</b></div><div class="receipt-line"><span>Diskon</span><b>{rupiah(showReceipt.discount)}</b></div><div class="receipt-line receipt-total"><span>TOTAL</span><b>{rupiah(showReceipt.total)}</b></div><div class="receipt-line"><span>{showReceipt.payment} · Dibayar</span><b>{rupiah(showReceipt.paid)}</b></div><div class="receipt-line"><span>Kembalian</span><b>{rupiah(showReceipt.change)}</b></div><hr/><div class="receipt-center thanks">Terima kasih atas kepercayaan Anda.<br/>Simpan nota sebagai bukti pembelian.</div></div></section></div>{/if}
{#if notice}<div class="toast"><Check size={16}/>{notice}<button aria-label="Tutup notifikasi" onclick={()=>notice=''}><X size={14}/></button></div>{/if}

